cat > /app/test_validation.py << 'PYEOF'
import importlib.util, importlib.machinery, json, copy, random, math
loader = importlib.machinery.SourceFileLoader("runmod", "/app/submit/run")
spec = importlib.util.spec_from_loader("runmod", loader)
R = importlib.util.module_from_spec(spec); loader.exec_module(R)

def build_image_raw(fib, cuts, caps, ms):
    stages, used = R.build_stages(fib, cuts, ms)
    num,den = R.max_ratio(used,caps)
    return {"status":"ok","capacities":caps,"max_stride":ms,"cuts":cuts,
            "stages":stages,"used_bits":used,"peak":{"num":num,"den":den}}

fib=[(R.parse_prefix(p)[0],R.parse_prefix(p)[1],h) for p,h in [
    ("::/0",7),("2001:db8::/32",8),("2001:db8::1/128",9),("2001:db8:1::/48",3),("2001:db8:2::/48",3)]]
caps=[4096,4096,4096,4096]
ms=32
img=build_image_raw(fib,[0,32,64,96,128],caps,ms)
# valid lookup empty addresses
print("valid empty:", R.handle_lookup({"op":"lookup","image":copy.deepcopy(img),"addresses":[]}))
# different cuts valid image (needs to satisfy stride): [0,32,64,96,128] only for stride32,S4. Use S=8 stride16 -> [0,16,32,...]
caps8=[4096]*8
img8=build_image_raw(fib,[0,16,32,48,64,80,96,112,128],caps8,16)
try:
    r=R.handle_lookup({"op":"lookup","image":copy.deepcopy(img8),"addresses":["2001:db8::1"]})
    print("altcuts valid:", r)
except R.Invalid:
    print("ALT CUTS REJECTED (BAD)")

def expect_invalid(name, mut):
    im=copy.deepcopy(img)
    mut(im)
    try:
        R.handle_lookup({"op":"lookup","image":im,"addresses":[]})
        print("NOT REJECTED:",name)
    except R.Invalid:
        print("rejected:",name)
    except Exception as e:
        print("WRONG EXC",name,type(e),e)

expect_invalid("used+1", lambda m: m["used_bits"].__setitem__(0,m["used_bits"][0]+1))
expect_invalid("peak den", lambda m: m["peak"].__setitem__("den",m["peak"]["den"]+1))
expect_invalid("peak not reduced", lambda m: (m["peak"].__setitem__("num",m["peak"]["num"]*2),m["peak"].__setitem__("den",m["peak"]["den"]*2)) )
expect_invalid("status", lambda m: m.__setitem__("status","xx"))
expect_invalid("extra top", lambda m: m.__setitem__("z",1))
expect_invalid("cap extra", lambda m: m["capacities"].append(5))
expect_invalid("cuts unsorted", lambda m: m["cuts"].__setitem__(1,0))
expect_invalid("stride big", lambda m: m.__setitem__("max_stride",100))
def m_drop_edge(m):
    for st in m["stages"]:
        for nd in st["nodes"]:
            if nd["edges"]:
                nd["edges"].pop(); return
expect_invalid("drop edge", m_drop_edge)
def m_child(m):
    for st in m["stages"]:
        for nd in st["nodes"]:
            for ed in nd["edges"]:
                ed["child"]=999; return
expect_invalid("bad child", m_child)
def m_extra_rule_key(m):
    m["stages"][0]["nodes"][0]["rules"][0]["x"]=1
expect_invalid("rule extra key", m_extra_rule_key)
def m_noncanon(m):
    # replace a rule prefix with expanded equivalent
    r=m["stages"][0]["nodes"][0]["rules"][0]
    v,l=R.parse_prefix(r["prefix"])
    # build fully expanded
    groups=[(v>>(112-16*i))&0xffff for i in range(8)]
    r["prefix"]=":".join("%x"%g for g in groups)+"/%d"%l
expect_invalid("noncanonical", m_noncanon)
def m_dup_route(m):
    # append duplicate of an existing rule into same node's rules
    nd=m["stages"][0]["nodes"][0]
    if nd["rules"]:
        nd["rules"].append(copy.deepcopy(nd["rules"][0]))
expect_invalid("dup route", m_dup_route)
def m_reorder_rules(m):
    nd=m["stages"][0]["nodes"][0]
    if len(nd["rules"])>=2: nd["rules"].reverse()
expect_invalid("rule order", m_reorder_rules)
def m_drop_rule(m):
    for st in m["stages"]:
        for nd in st["nodes"]:
            if nd["rules"]: nd["rules"].pop(); return
expect_invalid("drop rule", m_drop_rule)
def m_misplace(m):
    # move a rule to a wrong node/stage (append to last stage node)
    nd=m["stages"][0]["nodes"][0]
    if len(nd["rules"])>1:
        r=nd["rules"].pop()
        m["stages"][-1]["nodes"][-1]["rules"].append(r)
expect_invalid("misplaced", m_misplace)
PYEOF
